mapper.select:
SELECT
    app_service AS appService,
    service_id AS serviceId,
    sum(request) AS totalRequests,
    sum(server_error) AS totalErrors,
    sum(response) AS totalResponses,
    if(totalResponses = 0, 0, round(totalErrors / totalResponses, 4)) AS errorRate,
    if(sum(rrt_count) = 0, 0, sum(rrt_sum) / sum(rrt_count)) AS avgRttMicroseconds,
    round(avgRttMicroseconds / 1000.0, 3) AS avgRttMs
FROM `${database}`.`${tableName}`
PREWHERE team_id = #{teamId}

    WHERE ${filter}

GROUP BY app_service, service_id

WITH grouped AS ( SELECT app_service, any(app_instance) AS app_instance, any(az_id) AS az_id, any(host_id) AS host_id, any(pod_cluster_id) AS pod_cluster_id, any(pod_ns_id) AS pod_ns_id, any(pod_group_id) AS pod_group_id, any(pod_id) AS pod_id, any(pod_node_id) AS pod_node_id, any(service_id) AS service_id, any(l3_epc_id) AS l3_epc_id, any(subnet_id) AS subnet_id, any(l3_device_id) AS l3_device_id, any(l3_device_type) AS l3_device_type, any(auto_instance_id) AS auto_instance_id, any(auto_instance_type) AS auto_instance_type, any(auto_service_id) AS auto_service_id, any(auto_service_type) AS auto_service_type, any(is_ipv4) AS is_ipv4, any(ip4) AS ip4, any(ip6) AS ip6, any(server_port) AS server_port, sum(request) AS total_requests, sum(server_error) AS total_errors, sum(response) AS total_responses, if(total_responses = 0, 0, round(total_errors / total_responses, 4)) AS error_rate, if(sum(rrt_count) = 0, 0, sum(rrt_sum) / sum(rrt_count)) AS avg_rtt_microseconds FROM `${database}`.`${tableName}` PREWHERE team_id = #{teamId}
AND ${filter}
GROUP BY app_service ) SELECT app_service AS appService, dictGetOrDefault('flow_tag.az_map', 'name', toUInt64(az_id), toString(az_id)) AS azName, dictGetOrDefault('flow_tag.device_map', 'name', (toUInt64(auto_service_type), toUInt64(auto_service_id)), toString(auto_service_id)) AS autoServiceName, dictGetOrDefault('flow_tag.chost_map', 'name', toUInt64(host_id), toString(host_id)) AS hostName, dictGetOrDefault('flow_tag.pod_cluster_map', 'name', toUInt64(pod_cluster_id), toString(pod_cluster_id)) AS podClusterName, dictGetOrDefault('flow_tag.pod_ns_map', 'name', toUInt64(pod_ns_id), toString(pod_ns_id)) AS podNsName, dictGetOrDefault('flow_tag.pod_group_map', 'name', toUInt64(pod_group_id), toString(pod_group_id)) AS podGroupName, dictGetOrDefault('flow_tag.pod_map', 'name', toUInt64(pod_id), toString(pod_id)) AS podName, dictGetOrDefault('flow_tag.pod_node_map', 'name', toUInt64(pod_node_id), toString(pod_node_id)) AS podNodeName, dictGetOrDefault('flow_tag.pod_service_map', 'name', toUInt64(service_id), toString(service_id)) AS serviceName, dictGetOrDefault('flow_tag.l3_epc_map', 'name', toUInt64(l3_epc_id), toString(l3_epc_id)) AS l3EpcName, dictGetOrDefault('flow_tag.subnet_map', 'name', toUInt64(subnet_id), toString(subnet_id)) AS subnetName, dictGetOrDefault('flow_tag.device_map', 'name', (toUInt64(l3_device_type), toUInt64(l3_device_id)), toString(l3_device_id)) AS l3DeviceName, dictGetOrDefault('flow_tag.device_map', 'name', (toUInt64(auto_instance_type), toUInt64(auto_instance_id)), toString(auto_instance_id)) AS autoInstanceName, is_ipv4 AS isIpv4, IPv4NumToString(ip4) AS ip4, IPv6NumToString(ip6) AS ip6, server_port AS serverPort, total_requests AS totalRequests, total_errors AS totalErrors, error_rate AS errorRate, avg_rtt_microseconds AS avgRttMicroseconds FROM grouped

SELECT service_id_0 AS srcNodeId, service_id_1 AS destNodeId, sum(request) AS totalRequests, sum(server_error) AS totalErrors, sum(response) AS totalResponses, if(totalResponses = 0, 0, round(totalErrors / totalResponses, 4)) AS errorRate, if(sum(rrt_count) = 0, 0, sum(rrt_sum) / sum(rrt_count)) AS avgRttMicroseconds FROM `${database}`.`${tableName}` PREWHERE team_id = #{teamId}
AND ${filter}
GROUP BY service_id_0, service_id_1

SELECT start_time AS startTime, response_duration AS responseDuration, app_service AS appService, l7_protocol AS l7Protocol, request_domain AS requestDomain, request_resource AS requestResource, endpoint, response_code AS responseCode, app_instance AS appInstance, ip4_0 AS ip40, ip4_1 AS ip41, ip6_0 AS ip60, ip6_1 AS ip61, client_port AS clientPort, server_port AS serverPort, is_tls AS isTls, process_id_0 AS processId0, process_id_1 AS processId1, attribute_names AS attributeNames, attribute_values AS attributeValues FROM `${database}`.`${tableName}` PREWHERE team_id = #{teamId} AND span_kind = 2
where ${filter}
LIMIT #{pageSize} OFFSET ( (#{pageIndex} -1) * #{pageSize} )

SELECT count(*) AS totalCount
FROM `${database}`.`${tableName}`
PREWHERE team_id = #{teamId}
AND span_kind = 2

    where ${filter}
